pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C(address(this), address(this), address(this));
    }

    function testFuzz_property(
        address _baseToken,
        address _nft,
        uint128 _virtualBaseTokenReserves,
        uint128 _virtualNftReserves,
        uint56 _changeFee,
        uint16 _feeRate,
        bytes32 _merkleRoot,
        bool _useStolenNftOracle,
        bool _payRoyalties
    ) public {
        vm.assume(_feeRate <= 5000);

        try c.initialize(
            _baseToken,
            _nft,
            _virtualBaseTokenReserves,
            _virtualNftReserves,
            _changeFee,
            _feeRate,
            _merkleRoot,
            _useStolenNftOracle,
            _payRoyalties
        ) {} catch {
            // If initialization reverts (e.g., AlreadyInitialized in a second call),
            // we consider it as an admissible scenario where the rule vacuously holds.
            // The rule is: whenever initialize succeeds, the stored changeFee must equal _changeFee.
            // So we skip the assertion if it reverts.
            return;
        }

        assertTrue(c.changeFee() == _changeFee);
    }
}

