pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }

    function testFuzz_property(
        address baseToken,
        address nft,
        uint128 virtualBase,
        uint128 virtualNft,
        uint56 changeFee,
        uint16 feeRate,
        bytes32 merkleRoot,
        bool useStolen,
        bool payRoyalties
    ) public {
        // keep feeRate in the admissible range
        vm.assume(feeRate <= 5_000);
        // `nft` and `baseToken` can be any address (including address(0) for ETH baseToken)
        // `virtualNft` must be > 0 for the contract to pass the only meaningful check
        // but initialize itself doesn't enforce that; we just give full freedom.

        // make sure the call does not revert for unexpected reasons (e.g. AlreadyInitialized)
        // we call once, then assert the invariant.
        try c.initialize(baseToken, nft, virtualBase, virtualNft, changeFee, feeRate, merkleRoot, useStolen, payRoyalties) {
            // after a successful call, initialized must be true
            assertTrue(c.initialized());
        } catch {
            // if it reverted (e.g. AlreadyInitialized or FeeRateTooHigh we already assumed away),
            // we do not check the invariant on a failed call — the invariant only concerns successful completion.
        }
    }
}

