import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }
    function testFuzz_property(bool _payRoyalties) public {
        // The bug flips _payRoyalties in the assignment, so we check equality after initialize.
        // We need to supply all other arguments; the fuzzer only needs to vary _payRoyalties.
        address _baseToken = address(0);
        address _nft = address(0);
        uint128 _virtualBaseTokenReserves = 1;
        uint128 _virtualNftReserves = 1;
        uint56 _changeFee = 0;
        uint16 _feeRate = 0;
        bytes32 _merkleRoot = bytes32(0);
        bool _useStolenNftOracle = false;

        c.initialize(
            _baseToken,
            _nft,
            _virtualBaseTokenReserves,
            _virtualNftReserves,
            _changeFee,
            _feeRate,
            _merkleRoot,
            _useStolenNftOracle,
            _payRoyalties
        );

        assertTrue(c.payRoyalties() == _payRoyalties);
    }
}
